function sigil(key){return '<svg viewBox="0 0 32 32">'+(SIGILS[key]||SIGILS.book)+'</svg>'}
function schoolSigilKey(school){const map={'Abjuração':'school-abjuration','Conjuração':'school-conjuration','Adivinhação':'school-divination','Encantamento':'school-enchantment','Evocação':'school-evocation','Ilusão':'school-illusion','Necromancia':'school-necromancy','Transmutação':'school-transmutation','Psiônica':'school-psionic','Escola não informada':'school-unknown','Escola especial':'school-unknown'};return map[String(school||'').trim()]||'school-unknown'}
