function esc(value){return String(value??'').replace(/[&<>'"]/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[ch]))}
function attr(value){return esc(value).replace(/`/g,'&#96;')}
function slugify(s){return String(s).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,'-').replace(/(^-|-$)/g,'')}
function formatText(value){return esc(value||'').split(/\n{2,}/).filter(Boolean).map(p=>'<p>'+p.replace(/\n/g,'<br>')+'</p>').join('')||'<p>Sem descrição.</p>'}
function formatRichText(value){
 const safe=esc(value||'').replace(/\r/g,'');
 if(!safe)return '<p>Sem descrição.</p>';
 return safe.split(/\n{2,}/).filter(Boolean).map(block=>{
  const lines=block.split(/\n/).map(x=>x.trim()).filter(Boolean);
  if(lines.length&&lines.every(x=>x.startsWith('•')))return '<ul>'+lines.map(x=>'<li>'+x.replace(/^•\s*/, '')+'</li>').join('')+'</ul>';
  let cooked=lines.join('<br>');
  cooked=cooked.replace(/(^|<br>)(PONTOS DE VIDA|PROFICIÊNCIAS|EQUIPAMENTO|TRUQUES|GRIMÓRIO|HABILIDADE DE CONJURAÇÃO|FOCO DE CONJURAÇÃO)(?=<br>|$)/g,'$1<strong class="inline-heading">$2</strong>');
  return '<p>'+cooked+'</p>';
 }).join('');
}
