function spellListKey(value){return String(value||'').normalize('NFD').replace(/[̀-ͯ]/g,'').toLocaleLowerCase('en').replace(/[’‘]/g,"'").replace(/[^a-z0-9']+/g,' ').replace(/\s+/g,' ').trim()}function addClassToSpell(spell,className){const classes=String(spell.classes||'').split(',').map(x=>x.trim()).filter(Boolean);if(!classes.includes(className))classes.push(className);return {...spell,classes:classes.join(', ')}}function addArtificerClass(spell){if(String(spell?.id||'').startsWith('spellblade-'))return spell;const listed=ARTIFICER_CLASS_SPELL_NAMES.has(spellListKey(spell.originalName))||ARTIFICER_CLASS_SPELL_NAMES.has(spellListKey(spell.name));return listed?addClassToSpell(spell,'Artífice'):spell}function addSpellbladeClass(spell){const listed=SPELLBLADE_CLASS_SPELL_NAMES.has(spellListKey(spell.originalName))||SPELLBLADE_CLASS_SPELL_NAMES.has(spellListKey(spell.name));return listed?addClassToSpell(spell,'Spellblade'):spell}function allSpells(){const builtins=new Map();CONTENT_REGISTRY.getSpellCatalogs().forEach(catalog=>catalog.spells.forEach(raw=>{if(!raw?.id||builtins.has(raw.id))return;const tagged={...raw,_catalogId:catalog.id,_sourceId:raw.sourceId||catalog.sourceId};builtins.set(raw.id,addSpellbladeClass(addArtificerClass(tagged)))}));const ids=new Set(customSpells.map(s=>s.id));return [...builtins.values()].filter(s=>!ids.has(s.id)).concat(customSpells)}
function spellSourceGroup(s){if(isCustom('spell',s?.id))return CONTENT_REGISTRY.getSource('custom')?.filterLabel||'Conteúdo próprio';return CONTENT_REGISTRY.spellGroupLabel(s)||CONTENT_REGISTRY.sourceFilterLabel(s)||'Fonte não registrada'}
function spellSourceGroups(s){const groups=CONTENT_REGISTRY.spellGroupLabels(s);if(!groups.length)groups.push(spellSourceGroup(s));return [...new Set(groups.filter(Boolean))]}
function spellSourceLabel(s,group){const base=String(s?.source||group||'');return s?.sourcePage&&!/\bp\.\s*\d+/i.test(base)?base+' · p. '+s.sourcePage:base}
function homeSourceText(){return CONTENT_REGISTRY.naturalList(CONTENT_REGISTRY.getSources({showOnHome:true}).map(source=>source.homeLabel||source.shortTitle||source.title))}
function spellCatalogSummary(){const stats=CONTENT_REGISTRY.catalogStats();const total=stats.reduce((sum,item)=>sum+item.count,0);const parts=stats.map(item=>item.count+' ('+item.label+')');return 'Catálogo em português com '+total+' registros-base distribuídos entre '+CONTENT_REGISTRY.naturalList(parts)+'.'}
function registeredSourceAboutCards(){return CONTENT_REGISTRY.getSources({showInAbout:true}).map(source=>'<div class="license-card"><strong style="color:var(--text)">'+esc(source.title)+'</strong>'+((source.about||[]).map(text=>'<p>'+esc(text)+'</p>').join(''))+'</div>').join('')}
function getClass(id){return allClasses().find(c=>c.id===id)}function getSubclass(id){return allSubclasses().find(s=>s.id===id)}function getSpell(id){return allSpells().find(s=>s.id===id)}function subclassesOf(id){return allSubclasses().filter(s=>s.classId===id)}function isCustom(type,id){return(type==='spell'?customSpells:type==='class'?customClasses:customSubclasses).some(x=>x.id===id)}
function routeHref(view,id,extra){return DEEP_LINKS.href(view,id,extra||{})}
function routeAnchor(view,id,label,className='',extra={}){return '<a href="'+attr(routeHref(view,id,extra))+'" data-grimorio-route class="'+attr(className)+'">'+label+'</a>'}
