function shareLinkButton(view,id,extra,label='Copiar link'){const payload=encodeURIComponent(JSON.stringify(extra||{}));return '<button class="action-btn deep-link-button" type="button" data-route-copy-view="'+attr(view)+'" data-route-copy-id="'+attr(id||'')+'" data-route-copy-extra="'+attr(payload)+'" onclick="copyRouteLinkFromButton(this)" title="Copiar link direto"><span aria-hidden="true">🔗</span><span class="deep-link-label">'+esc(label)+'</span></button>'}
function copyRouteLinkFromButton(button){let extra={};try{extra=JSON.parse(decodeURIComponent(button?.dataset?.routeCopyExtra||'%7B%7D'))}catch(_){}return copyRouteLink(button?.dataset?.routeCopyView||'home',button?.dataset?.routeCopyId||null,extra)}
