function loadCustomData(){const d=readLocal(STORAGE_KEY,{});customClasses=Array.isArray(d.classes)?d.classes:[];customSubclasses=Array.isArray(d.subclasses)?d.subclasses:[];customSpells=Array.isArray(d.spells)?d.spells:[];favorites=new Set(Array.isArray(d.favorites)?d.favorites:[]);notes=d.notes&&typeof d.notes==='object'?d.notes:{}}
